-- Serviços do site da Clean Car — 16/10/2026
-- Mesmo catálogo do SAS (planilha de processos do Glauber).
-- Rodar UMA vez no SQL Editor do Supabase do SITE (não do SAS).
-- Seguro para rodar de novo: atualiza o que existe e cria o que falta.

begin;

insert into services (slug, nome, resumo, descricao, duracao, preco_desde, imagem_url, tag, pontos_fidelidade, ordem, termo_popular, ativo)
values ('lavagem-bronze', 'Lavagem Bronze', 'Manutenção do dia a dia, rápida e segura para a pintura.', 'Lavagem de manutenção com espuma densa (snow foam) e shampoo neutro, esfregação com luva de microfibra que não agride o verniz, limpeza das rodas e caixas de roda, pretinho nos pneus e secagem com toalha macia. Por dentro, aspiração de manutenção de carpetes e bancos e limpeza básica. Ideal para manter o carro sempre apresentável.', '45min', '45', 'https://images.unsplash.com/photo-1520340356584-f9917d1eea6f?auto=format&fit=crop&w=800&q=80', null, 2, 1, 'Lavagem de Carro', true)
on conflict (slug) do update set nome = excluded.nome, resumo = excluded.resumo, descricao = excluded.descricao, duracao = excluded.duracao, preco_desde = excluded.preco_desde, tag = excluded.tag, ordem = excluded.ordem, termo_popular = excluded.termo_popular, ativo = excluded.ativo, updated_at = now();

insert into services (slug, nome, resumo, descricao, duracao, preco_desde, imagem_url, tag, pontos_fidelidade, ordem, termo_popular, ativo)
values ('lavagem-prata', 'Lavagem Prata', 'Limpeza completa com selante: brilho e água escorrendo na chuva.', 'Pré-lavagem e lavagem com espuma densa e shampoo neutro, esfregação com luva de microfibra, limpeza das rodas e caixas de roda, selante que protege a pintura e faz a água escorrer, pretinho e secagem com toalha macia. Por dentro: aspiração de carpetes, bancos e porta-malas, limpeza de painel, console, portas e volante, vidros internos e sanitizante perfumado. Brinde: saquinho de lixo para o carro e cheirinho. Garantia de 24h.', '1h30', '85', 'https://images.unsplash.com/photo-1607860108855-64acf2078ed9?auto=format&fit=crop&w=800&q=80', null, 5, 2, 'Lavagem de Carro Completa', true)
on conflict (slug) do update set nome = excluded.nome, resumo = excluded.resumo, descricao = excluded.descricao, duracao = excluded.duracao, preco_desde = excluded.preco_desde, tag = excluded.tag, ordem = excluded.ordem, termo_popular = excluded.termo_popular, ativo = excluded.ativo, updated_at = now();

insert into services (slug, nome, resumo, descricao, duracao, preco_desde, imagem_url, tag, pontos_fidelidade, ordem, termo_popular, ativo)
values ('lavagem-ouro', 'Lavagem Ouro', 'Padrão show-room, dentro e fora, com detalhamento a pincel.', 'Nossa lavagem mais completa. Por fora: pré-lavagem, espuma densa e shampoo neutro, detalhamento a pincel de frestas, emblemas e molduras de portas e porta-malas, limpeza profunda das rodas e caixas de roda, selante na pintura, pretinho e secagem com toalha macia. Por dentro: pincel em painel, console, portas, colunas, volante, saídas de ar e pedaleiras, aspiração premium, vidros internos e sanitizante perfumado. Brinde: saquinho de lixo e cheirinho. Garantia de 24h.', '3h40', '220', 'https://images.unsplash.com/photo-1617814076367-b759c7d7e738?auto=format&fit=crop&w=800&q=80', 'Mais pedido', 10, 3, 'Lavagem de Carro Premium', true)
on conflict (slug) do update set nome = excluded.nome, resumo = excluded.resumo, descricao = excluded.descricao, duracao = excluded.duracao, preco_desde = excluded.preco_desde, tag = excluded.tag, ordem = excluded.ordem, termo_popular = excluded.termo_popular, ativo = excluded.ativo, updated_at = now();

insert into services (slug, nome, resumo, descricao, duracao, preco_desde, imagem_url, tag, pontos_fidelidade, ordem, termo_popular, ativo)
values ('higienizacao', 'Higienização Interna VIP', 'Interior limpo de verdade: bancos, teto e carpetes higienizados.', 'Limpeza profunda de todo o interior: bancos, teto, carpetes e porta-malas com esfregação, bactericida e extração, que retiram a sujeira impregnada, ácaros, fungos e odores. Detalhamento a pincel de portas, colunas, volante, saídas de ar e pedaleiras, sanitizante perfumado e brinde. O carro fica o dia todo e sai levemente úmido: deixe os vidros abertos por 12h. Garantia de 72h para mancha ou odor que persistir.', '8h', '420', 'https://images.unsplash.com/photo-1506015391300-4802dc74de2e?auto=format&fit=crop&w=800&q=80', 'Saúde da família', 30, 4, 'Higienização de Estofados e Bancos do Carro', true)
on conflict (slug) do update set nome = excluded.nome, resumo = excluded.resumo, descricao = excluded.descricao, duracao = excluded.duracao, preco_desde = excluded.preco_desde, tag = excluded.tag, ordem = excluded.ordem, termo_popular = excluded.termo_popular, ativo = excluded.ativo, updated_at = now();

insert into services (slug, nome, resumo, descricao, duracao, preco_desde, imagem_url, tag, pontos_fidelidade, ordem, termo_popular, ativo)
values ('higienizacao-banco-dianteiro', 'Higienização de Banco Dianteiro', 'Banco do motorista ou do passageiro limpo por completo (valor por banco).', 'Higienização profunda de um banco da frente: aspiração detalhada, esfregação com produto de limpeza profunda, bactericida e extração de sujeira e umidade, e sanitizante perfumado. Valor por banco. Sai levemente úmido: deixe os vidros abertos por 12h. Garantia de 72h para mancha ou odor que persistir.', '2h', '99', 'https://images.unsplash.com/photo-1616455579100-2ceaa4eb2d37?auto=format&fit=crop&w=800&q=80', null, 5, 5, 'Limpeza de Banco de Carro', true)
