insert into services (slug, nome, resumo, descricao, duracao, preco_desde, imagem_url, tag, pontos_fidelidade, ordem, termo_popular, ativo)
values ('higienizacao-banco-traseiro', 'Higienização de Banco Traseiro', 'Assento e encostos traseiros limpos por completo.', 'Higienização profunda do banco traseiro: aspiração detalhada, esfregação com produto de limpeza profunda, bactericida e extração, que remove restos de comida, derramamentos e sujeira impregnada, e sanitizante perfumado. Ideal para quem transporta crianças, pets ou passageiros. Sai levemente úmido: deixe os vidros abertos por 12h. Garantia de 72h para mancha ou odor que persistir.', '2h', '120', 'https://images.unsplash.com/photo-1616455579100-2ceaa4eb2d37?auto=format&fit=crop&w=800&q=80', null, 10, 6, 'Limpeza de Banco Traseiro do Carro', true)
