insert into services (slug, nome, resumo, descricao, duracao, preco_desde, imagem_url, tag, pontos_fidelidade, ordem, termo_popular, ativo)
values ('revitalizacao-plastico', 'Revitalização de Plásticos Internos', 'Painel, console e portas com a cor de volta e protegidos.', 'Descontaminação que remove gordura e poeira dos plásticos internos, limpeza profunda a pincel com sanitizante bactericida e aplicação de revitalizador com selante: devolve a cor original, protege e deixa acabamento seco ao toque, sem aspecto oleoso. Durabilidade média de 30 a 60 dias, conforme a exposição ao sol.', '1h', '120', 'https://images.unsplash.com/photo-1552519507-da3b142c6e3d?auto=format&fit=crop&w=800&q=80', null, 5, 7, 'Plástico Interno do Carro Desbotado', true)
