insert into services (slug, nome, resumo, descricao, duracao, preco_desde, imagem_url, tag, pontos_fidelidade, ordem, termo_popular, ativo)
values ('revitalizacao-plastico-externo', 'Revitalização de Plásticos Externos', 'Para-choques, retrovisores e frisos pretos de novo.', 'Descontaminação que remove gordura e poeira dos plásticos externos (para-choques, retrovisores, molduras e frisos), limpeza profunda a pincel e aplicação de revitalizador com selante: devolve o preto original e protege do sol, sem aspecto oleoso. Durabilidade média de 30 a 60 dias, conforme a exposição ao sol.', '1h', '110', 'https://images.unsplash.com/photo-1552519507-da3b142c6e3d?auto=format&fit=crop&w=800&q=80', null, 5, 8, 'Plástico do Carro Esbranquiçado ou Desbotado', true)
