insert into services (slug, nome, resumo, descricao, duracao, preco_desde, imagem_url, tag, pontos_fidelidade, ordem, termo_popular, ativo)
values ('restauracao-de-farol', 'Restauração de Faróis', 'Faróis transparentes e mais segurança à noite.', 'Descontaminação e isolamento da área, lixamento da lente quando necessário, polímero revitalizador e selante de proteção. A transparência volta e a iluminação melhora à noite, sem trocar a peça. Durabilidade média de 6 a 9 meses, conforme a exposição ao sol. Umidade dentro do farol não é revitalização: é vedação, feita pelo mecânico. Garantia de 48h para manchas que persistirem.', '2h', '200', 'https://images.unsplash.com/photo-1503376780353-7e6692767b70?auto=format&fit=crop&w=800&q=80', null, 10, 9, 'Restauração de Faróis Amarelados', true)
