insert into services (slug, nome, resumo, descricao, duracao, preco_desde, imagem_url, tag, pontos_fidelidade, ordem, termo_popular, ativo)
values ('lavagem-motor', 'Limpeza Estética do Motor (a seco)', 'Cofre do motor limpo e conservado, sem jato de água.', 'Serviço de estética e conservação: deixa o cofre do motor limpo, sem gordura e com acabamento renovado, sem água sob pressão para proteger a parte elétrica. Não é diagnóstico: para localizar vazamentos, o indicado é o seu mecânico. Com o motor limpo, fica mais fácil perceber um vazamento novo nos dias seguintes. Feito junto com uma lavagem.', '2h', '125', 'https://images.unsplash.com/photo-1621905251189-08b45d6a269e?auto=format&fit=crop&w=800&q=80', null, 10, 10, 'Limpeza de Motor de Carro', false)
on conflict (slug) do update set nome = excluded.nome, resumo = excluded.resumo, descricao = excluded.descricao, duracao = excluded.duracao, preco_desde = excluded.preco_desde, tag = excluded.tag, ordem = excluded.ordem, termo_popular = excluded.termo_popular, ativo = excluded.ativo, updated_at = now();

insert into services (slug, nome, resumo, descricao, duracao, preco_desde, imagem_url, tag, pontos_fidelidade, ordem, termo_popular, ativo)
values ('cristalizacao-de-vidros', 'Cristalização de Vidros', 'Água escorrendo sozinha e visão clara na chuva.', 'Descontaminação dos vidros, remoção de manchas de chuva ácida e marcas d''água, e aplicação de cristalizador com selante: a água escorre sozinha com o carro em movimento e a visão melhora na chuva. Durabilidade média de 3 meses; lavando na Clean Car a partir da Lavagem Prata, pelo menos 6 meses. Feito junto com uma lavagem.', '2h', '180', 'https://images.unsplash.com/photo-1519641471654-76ce0107ad1b?auto=format&fit=crop&w=800&q=80', null, 10, 11, 'Remoção de Chuva Ácida do Vidro do Carro', true)
