insert into services (slug, nome, resumo, descricao, duracao, preco_desde, imagem_url, tag, pontos_fidelidade, ordem, termo_popular, ativo)
values ('hidratacao-de-couro', 'Hidratação de Couro', 'Bancos de couro macios e protegidos.', 'Limpeza profunda e descontaminação do couro e aplicação de hidratante específico para couro automotivo: devolve a maciez e ajuda a evitar ressecamento, manchas e rachaduras. Durabilidade média de 3 a 6 meses, conforme a frequência de limpeza e a exposição ao sol ou à umidade.', '2h', '210', 'https://images.unsplash.com/photo-1616455579100-2ceaa4eb2d37?auto=format&fit=crop&w=800&q=80', null, 10, 12, 'Hidratação de Banco de Couro do Carro', true)
