insert into services (slug, nome, resumo, descricao, duracao, preco_desde, imagem_url, tag, pontos_fidelidade, ordem, termo_popular, ativo)
values ('tratamento-anti-odor', 'Tratamento Anti-Odor com Ozônio', 'Ozônio nos dutos do ar e na cabine contra o mau cheiro.', 'Tratamento com ozônio que higieniza os dutos do ar-condicionado e o interior, ajudando a eliminar bactérias e odores. Feito junto com uma lavagem. Para cheiro forte e impregnado no tecido, como cigarro ou mofo, o ideal é combinar com a Higienização Interna.', '1h', '120', 'https://images.unsplash.com/photo-1506015391300-4802dc74de2e?auto=format&fit=crop&w=800&q=80', null, 10, 13, 'Tirar Mau Cheiro do Carro', true)
