insert into services (slug, nome, resumo, descricao, duracao, preco_desde, imagem_url, tag, pontos_fidelidade, ordem, termo_popular, ativo)
values ('lavagem-pesada-de-rodas', 'Lavagem Pesada de Rodas e Caixas de Roda', 'Rodas sem pó de freio e caixas de roda sem barro.', 'Limpeza pesada das rodas e caixas de roda, sem desmontar: lavagem detalhada com espuma densa e produtos específicos que removem barro e terra, descontaminação das rodas contra o pó de freio impregnado, limpeza de aros e raios, revitalizador nos plásticos da caixa de roda e pretinho com proteção UV nos pneus.', '2h', null, 'https://images.unsplash.com/photo-1617814076367-b759c7d7e738?auto=format&fit=crop&w=800&q=80', null, 10, 14, 'Limpeza de Rodas do Carro', false)
