insert into services (slug, nome, resumo, descricao, duracao, preco_desde, imagem_url, tag, pontos_fidelidade, ordem, termo_popular, ativo)
values ('enceramento-tecnico', 'Enceramento Técnico', 'Brilho espelhado e proteção da pintura por meses.', 'Cera de carnaúba aplicada com politriz e acabamento em microfibra: realça a cor, dá brilho espelhado e protege a pintura contra raios UV, seiva de árvores e fezes de pássaros. Durabilidade média de 3 meses; lavando na Clean Car a partir da Lavagem Prata, pelo menos 6 meses. Precisa de uma Lavagem Prata ou Ouro antes.', '3h', '195', 'https://images.unsplash.com/photo-1601362840469-51e4d8d58785?auto=format&fit=crop&w=800&q=80', null, 10, 15, 'Enceramento de Carro', true)
