insert into services (slug, nome, resumo, descricao, duracao, preco_desde, imagem_url, tag, pontos_fidelidade, ordem, termo_popular, ativo)
values ('higienizacao-de-estofados', 'Higienização de Estofados a Domicílio', 'Sofás, poltronas, colchões e cadeiras limpos na sua casa.', 'Vamos até a sua casa para higienizar sofás, poltronas, colchões e cadeiras: aspiração detalhada, esfregação com produto de limpeza profunda, bactericida e extração, e sanitizante perfumado. Cada peça é diferente, por isso o valor é passado depois de uma avaliação gratuita pelas fotos no WhatsApp. Mantenha o ambiente arejado depois. Garantia de 72h para odor ou mancha que persistir, exceto manchas que já tingiram o tecido.', null, null, '', 'A domicílio', 10, 16, 'Higienização de Sofá e Estofados', true)
on conflict (slug) do update set nome = excluded.nome, resumo = excluded.resumo, descricao = excluded.descricao, duracao = excluded.duracao, preco_desde = excluded.preco_desde, tag = excluded.tag, ordem = excluded.ordem, termo_popular = excluded.termo_popular, ativo = excluded.ativo, updated_at = now();

-- Proteção de Rodas saiu do catálogo (a página passa a responder 410).
update services set ativo = false, updated_at = now() where slug = 'protecao-de-rodas';

-- FAQ geral de garantia: agora a garantia depende do serviço.
update faqs set resposta = 'Sim. Lavagens: 24 horas para qualquer sujeira que tenha ficado do serviço. Higienizações: 72 horas para mancha ou odor que já existia e persistiu. Restauração de faróis: 48 horas para manchas que persistirem. A garantia não cobre sujeira nova, danos pré-existentes, desgaste natural ou uso inadequado.' where pergunta ilike '%garantia%';
update faqs set resposta = replace(replace(resposta, 'produtos Vonixx como Hidrox e Glasy,', 'selantes e cristalizadores profissionais Vonixx,'), 'Hidrox e Glasy', 'selantes e cristalizadores profissionais') where resposta ilike '%hidrox%' or resposta ilike '%glasy%';

commit;

select slug, nome, preco_desde, ativo from services order by ordem;
